### AJAX Cart Implementation

Add to cart with AJAX:
```javascript
// assets/cart.js

class CartManager {
  constructor() {
    this.cart = null;
    this.init();
  }

  async init() {
    await this.fetchCart();
    this.bindEvents();
  }

  async fetchCart() {
    try {
      const response = await fetch('/cart.js');
      this.cart = await response.json();
      this.updateCartUI();
      return this.cart;
    } catch (error) {
      console.error('Error fetching cart:', error);
    }
  }

  async addItem(variantId, quantity = 1, properties = {}) {
    try {
      const response = await fetch('/cart/add.js', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          id: variantId,
          quantity: quantity,
          properties: properties,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to add item to cart');
      }

      await this.fetchCart();
      this.showCartDrawer();
      return await response.json();
    } catch (error) {
      console.error('Error adding to cart:', error);
      this.showError(error.message);
    }
  }

  async updateItem(lineKey, quantity) {
    try {
      const response = await fetch('/cart/change.js', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          line: lineKey,
          quantity: quantity,
        }),
      });

      await this.fetchCart();
      return await response.json();
    } catch (error) {
      console.error('Error updating cart:', error);
    }
  }

  updateCartUI() {
    // Update cart count badge
    const cartCount = document.querySelector('.cart-count');
    if (cartCount) {
      cartCount.textContent = this.cart.item_count;
    }

    // Update cart drawer content
    const cartDrawer = document.querySelector('.cart-drawer');
    if (cartDrawer) {
      this.renderCartItems(cartDrawer);
    }
  }

  renderCartItems(container) {
    // Render cart items in drawer
    const itemsHTML = this.cart.items.map(item => `
      <div class="cart-item" data-line="${item.key}">
        <img src="${item.image}" alt="${item.title}" loading="lazy">
        <div class="cart-item__details">
          <h4>${item.product_title}</h4>
          <p>${item.variant_title}</p>
          <p class="cart-item__price">${this.formatMoney(item.final_line_price)}</p>
          <input 
            type="number" 
            value="${item.quantity}" 
            min="0" 
            data-line="${item.key}"
            class="cart-item__quantity"
          >
        </div>
      </div>
    `).join('');

    container.querySelector('.cart-items').innerHTML = itemsHTML;
    container.querySelector('.cart-total').textContent = this.formatMoney(this.cart.total_price);
  }

  formatMoney(cents) {
    return `$${(cents / 100).toFixed(2)}`;
  }

  showCartDrawer() {
    document.querySelector('.cart-drawer')?.classList.add('is-open');
  }

  bindEvents() {
    // Add to cart buttons
    document.addEventListener('click', (e) => {
      if (e.target.matches('[data-add-to-cart]')) {
        e.preventDefault();
        const variantId = e.target.dataset.variantId;
        this.addItem(variantId);
      }
    });

    // Quantity updates
    document.addEventListener('change', (e) => {
      if (e.target.matches('.cart-item__quantity')) {
        const line = e.target.dataset.line;
        const quantity = parseInt(e.target.value);
        this.updateItem(line, quantity);
      }
    });
  }

  showError(message) {
    // Show error notification
    console.error(message);
  }
}

// Initialize cart manager
document.addEventListener('DOMContentLoaded', () => {
  window.cartManager = new CartManager();
});
```

