// Flexible document modeling with validation

// User profile with embedded and referenced data
const userSchema = {
  validator: {
    $jsonSchema: {
      bsonType: "object",
      required: ["email", "profile", "createdAt"],
      properties: {
        _id: { bsonType: "objectId" },
