  });
}

function getCurrencyByCountry(country: string): string {
  const currencies: Record<string, string> = {
    'US': 'USD',
    'GB': 'GBP',
    'DE': 'EUR',
    'JP': 'JPY',
    'CA': 'CAD'
  };
