### Custom Hook with TypeScript Generics

```typescript
import { useState, useEffect } from "react";

interface UseFetchResult<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
  refetch: () => void;
}

export function useFetch<T>(url: string): UseFetchResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const [refetchCounter, setRefetchCounter] = useState(0);

  useEffect(() => {
    let cancelled = false;

    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        const response = await fetch(url);
        if (!response.ok) throw new Error(`HTTP error ${response.status}`);

        const json = await response.json();

        if (!cancelled) {
          setData(json);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err : new Error("Unknown error"));
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    fetchData();

    return () => {
      cancelled = true;
    };
  }, [url, refetchCounter]);

  const refetch = () => setRefetchCounter((prev) => prev + 1);

  return { data, loading, error, refetch };
}

// Usage with type inference
function UserList() {
  const { data, loading, error } = useFetch<User[]>("https://api.example.com/users");

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;
  if (!data) return null;

  return (
    <ul>
      {data.map((user) => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  );
}
```

### Error Boundary with TypeScript

```typescript
import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Error caught by boundary:", error, errorInfo);
    // Log to error reporting service
  }

  render() {
    if (this.state.hasError) {
      return (
        this.props.fallback || (
          <div role="alert">
            <h2>Something went wrong</h2>
            <details>
              <summary>Error details</summary>
              <pre>{this.state.error?.message}</pre>
            </details>
            <button onClick={() => this.setState({ hasError: false, error: null })}>Try again</button>
          </div>
        )
      );
    }

    return this.props.children;
  }
}
```

### Using cacheSignal for Resource Cleanup (React 19.2)

```typescript
import { cache, cacheSignal } from "react";

// Cache with automatic cleanup when cache expires
const fetchUserData = cache(async (userId: string) => {
  const controller = new AbortController();
  const signal = cacheSignal();

  // Listen for cache expiration to abort the fetch
  signal.addEventListener("abort", () => {
    console.log(`Cache expired for user ${userId}`);
    controller.abort();
  });

  try {
    const response = await fetch(`https://api.example.com/users/${userId}`, {
      signal: controller.signal,
    });

    if (!response.ok) throw new Error("Failed to fetch user");
    return await response.json();
  } catch (error) {
    if (error.name === "AbortError") {
      console.log("Fetch aborted due to cache expiration");
    }
    throw error;
  }
});

// Usage in component
function UserProfile({ userId }: { userId: string }) {
  const user = use(fetchUserData(userId));

  return (
    <div>
      <h2>{user.name}</h2>
      <p>{user.email}</p>
    </div>
  );
}
```

